code.regionString:
for i = 1:numel(x)

    if place == "xy"
        e1 = x0+x(i);
        e2 = y0+y(i);
        e3 = z0;
    elseif place == "xz"
        e1 = x0+x(i);
        e2 = y0;
        e3 = z0+y(i);
    else
        e1 = x0;
        e2 = y0+x(i);
        e3 = z0+y(i);
    end

    v = GenV(B, alf, bet, gam, e1, e2, e3);
    ax(i) = v(1,1);
    bx(i) = v(1,2);
    ay(i) = v(2,1);
    by(i) = v(2,2);
    az(i) = v(3,1);
    bz(i) = v(3,2);
end
